'use strict';
let area='today',editingArea='work';
const entries=k=>data[k]||[];
function switchArea(name){area=name;$('add').textContent=({today:'＋ Aggiungi un blocco',work:'＋ Attività di lavoro',family:'＋ Faccenda di famiglia',week:'＋ Aggiungi un blocco'})[name];$('add').onclick=()=>{if(name==='today'||name==='week')openEditor();else editDaily(name);};document.querySelectorAll('[data-area]').forEach(b=>{if(b.dataset.area===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});['today','work','family','week'].forEach(k=>$('panel-'+k).hidden=k!==name);if(name==='week'&&window.renderWeek)window.renderWeek();}
const nomeLuogo=id=>{const p=(data.places||[]).find(p=>p.id===id);return p?p.name:'';};
function taskRow(x,k){if(k==='shop')return `<article class="daily-row ${x.done?'finished':''}"><button class="tick" data-check="shop" data-id="${esc(x.id)}" aria-label="${x.done?'Segna da prendere':'Preso'}: ${esc(x.title)}" aria-pressed="${x.done}">${x.done?'✓':''}</button><div><strong>${esc(x.title)}</strong><p>${esc(x.qty||'')}</p></div><button class="quiet" data-edit="shop" data-id="${esc(x.id)}" aria-label="Modifica ${esc(x.title)}">Modifica</button></article>`;
 const dettaglio=k==='work'?`${x.priority?'★ Prima cosa · ':''}${x.minutes} min${x.actual?' · reali '+x.actual+' min':''}${x.date<$('date').value?' · Rimasta da '+niceDate(x.date):''}`:`${esc(x.person||'Da assegnare')} · ${x.date?niceDate(x.date):'Quando puoi'}${({none:'',daily:' · Ogni giorno',weekly:' · Ogni settimana',monthly:' · Ogni mese',yearly:' · Ogni anno'})[x.repeat]||''}${x.notice?' · avviso '+({1:'1 giorno',3:'3 giorni',7:'1 settimana',14:'2 settimane',30:'1 mese'})[x.notice]+' prima':''}`;
 return `<article class="daily-row ${x.done?'finished':''}"><button class="tick" data-check="${k}" data-id="${esc(x.id)}" aria-label="${x.done?'Segna da fare':'Completa'}: ${esc(x.title)}" aria-pressed="${x.done}" ${k==='family'&&x.done&&x.repeat!=='none'?'disabled':''}>${x.done?'✓':''}</button><div><strong>${esc(x.title)}</strong><p>${dettaglio}</p>${x.place&&nomeLuogo(x.place)?`<p class="note-line">◎ ${esc(nomeLuogo(x.place))}</p>`:''}${x.note?`<p class="note-line">${esc(x.note)}</p>`:''}</div><button class="quiet" data-edit="${k}" data-id="${esc(x.id)}" aria-label="Modifica ${esc(x.title)}">Modifica</button></article>`;}

function shift(){return data.blocks.find(b=>b.workShiftDay===$('date').value&&b.date===$('date').value);}
window.renderDaily=function(){const d=$('date').value,w=entries('work').filter(x=>(x.date===d||x.date<d&&!x.done)).sort((a,b)=>Number(a.done)-Number(b.done)||Number(b.priority)-Number(a.priority)),f=entries('family').slice().sort((a,b)=>Number(a.done)-Number(b.done)||(a.date||'9999').localeCompare(b.date||'9999')),left=w.filter(x=>!x.done),familyDue=f.filter(x=>!x.done&&x.date&&x.date<=d),sh=shift();
$('workList').innerHTML=w.map(x=>taskRow(x,'work')).join('')||'<div class="list-empty">Qual è la prima cosa da fare al lavoro?<br>Aggiungila qui, anche senza un orario preciso.</div>';
const used=left.reduce((n,x)=>n+x.minutes,0),capacity=sh?Math.max(0,min(sh.end)-min(sh.start)-(sh.pauseMinutes||0)):null;
$('workSummary').textContent=`${left.length} da fare · ${used} min stimati${capacity!==null?' · '+capacity+' min nel turno'+(used>capacity?' — La lista supera il tempo disponibile. Sposta qualcosa.':' · '+(capacity-used)+' min di margine'):'. Riserva un turno per confrontare il carico.'}`;
$('carryWork').hidden=!left.length;$('shiftStatus').textContent=sh?`Riservato ${sh.start}–${sh.end}. Puoi modificarlo qui o eliminarlo da Oggi.`:'Nessun turno riservato per questa data.';
if(sh){$('shiftStart').value=sh.start;$('shiftEnd').value=sh.end;$('shiftBreak').value=sh.pauseMinutes||0;}
const sharedFamily=window.GiornoCloud?window.GiornoCloud.rows('family'):'';
$('familyList').innerHTML=sharedFamily+f.filter(x=>!x.done).map(x=>taskRow(x,'family')).join('')+(f.some(x=>x.done)?'<details><summary>Completate ('+f.filter(x=>x.done).length+')</summary>'+f.filter(x=>x.done).map(x=>taskRow(x,'family')).join('')+'</details>':'')||'<div class="list-empty">Spazzatura, bollette, visite o una commissione.<br>Scrivi chi se ne occupa, con una data solo se serve.</div>';
const sp=entries('shop'),sharedShop=window.GiornoCloud?window.GiornoCloud.rows('shop'):'';
$('shopList').innerHTML=sharedShop+[...sp].sort((a,b)=>Number(a.done)-Number(b.done)).map(x=>taskRow(x,'shop')).join('')||'<div class="list-empty">La lista è pronta per la prossima spesa.</div>';
$('shopSummary').textContent=sp.length||sharedShop?`${sp.filter(x=>!x.done).length} da prendere · compare da sola quando sei al supermercato`:'Compare da sola quando sei al supermercato.';
$('clearShop').hidden=!sp.some(x=>x.done);
const joined=!!(window.GiornoCloud&&window.GiornoCloud.joined());$('shopSharedWrap').hidden=!joined;if(!joined)$('shopShared').checked=false;$('familyShared').closest('label').hidden=!joined;$('sharedHint').hidden=!joined;if(!joined)$('familyShared').checked=false;
$('storageNote').textContent=joined?'Programma personale in questo browser · Liste di famiglia sincronizzate online':'Salvato in questo browser · Attiva “Famiglia online” per condividere liste e spesa';
const extraFamily=window.GiornoCloud?window.GiornoCloud.count('family'):0;
if(window.renderWeek)window.renderWeek();
$('dailyOverview').innerHTML=[['work','Lavoro',left.length+' attività'],['family','Famiglia',(familyDue.length+f.filter(x=>!x.done&&!x.date).length+extraFamily)+' da gestire'],['week','Settimana',(()=>{const n=(data.blocks||[]).filter(b=>!b.done&&b.date>=d&&b.date<=plus(d,6)).length;return n+(n===1?' blocco':' blocchi');})()]].map(([k,t,n])=>`<button data-go="${k}"><span>${t}</span><b>${n} →</b></button>`).join('');
};
function editDaily(k,x){editingArea=k;$('dailyForm').reset();$('dailyId').value=x?.id||'';$('dailyTitle').textContent=k==='work'?'Un’attività di lavoro':'Una faccenda di famiglia';$('dailyName').value=x?.title||'';$('dailyDate').value=x?.date||(k==='work'?$('date').value:'');$('dailyDate').required=k==='work';$('optionalDate').hidden=k==='work';$('workFields').hidden=k!=='work';$('familyFields').hidden=k!=='family';$('workMinutes').value=x?.minutes||30;$('workActual').value=x?.actual||'';$('workPriority').checked=!!x?.priority;$('dailyNote').value=x?.note||'';riempiLuoghi($('dailyPlace'),x?.place||'');$('workHint').textContent='';$('familyPerson').value=x?.person||'';$('familyRepeat').value=x?.repeat||'none';$('familyNotice').value=String(x?.notice||0);$('familyShared').checked=false;$('familyShared').disabled=!!x;$('dailyError').textContent='';$('deleteDaily').hidden=!x;$('dailyEditor').showModal();}
$('addWork').onclick=()=>editDaily('work');$('addFamily').onclick=()=>editDaily('family');
$('dailyForm').onsubmit=e=>{e.preventDefault();const k=editingArea,old=entries(k).find(x=>x.id===$('dailyId').value);
if(k==='family'&&!old&&$('familyShared').checked){const title=$('dailyName').value.trim();if(!title){$('dailyError').textContent='Scrivi che cosa c’è da fare.';return;}$('dailyEditor').close();window.GiornoCloud.add('family',title,$('familyPerson').value.trim());message('Aggiunta per tutta la famiglia.');return;}
const nota=$('dailyNote').value.trim(),reale=$('workActual').value.trim(),dove=$('dailyPlace').value;
const x={id:old?.id||crypto.randomUUID(),title:$('dailyName').value.trim(),date:$('dailyDate').value,done:old?.done||false,...(nota?{note:nota.slice(0,500)}:{}),...(dove?{place:dove}:{}),...(k==='work'?{minutes:Number($('workMinutes').value),priority:$('workPriority').checked,...(reale?{actual:Math.min(1440,Math.max(0,Math.round(Number(reale))))}:{})}:{person:$('familyPerson').value.trim(),repeat:$('familyRepeat').value,notice:Number($('familyNotice').value)})};if(!GiornoDaily.validExtra({[k]:[x]})){ $('dailyError').textContent='Controlla titolo, data e durata.';return;}if(k==='family'&&x.repeat!=='none'&&!x.date){$('dailyError').textContent='Scegli la prima data per una faccenda ricorrente.';return;}const n=structuredClone(data);n[k]=entries(k).filter(t=>t.id!==x.id).map(t=>k==='work'&&x.priority&&t.date===x.date?{...t,priority:false}:t);n[k].push(x);if(commit(n)){$('dailyEditor').close();message('Attività salvata');}};
$('deleteDaily').onclick=()=>{if(!confirm('Eliminare questa attività?'))return;const n=structuredClone(data);n[editingArea]=entries(editingArea).filter(x=>x.id!==$('dailyId').value);if(commit(n))$('dailyEditor').close();};
$('carryWork').onclick=()=>{const d=$('date').value;if(!confirm('Spostare a domani tutte le attività di lavoro non completate di questa giornata?'))return;const n=structuredClone(data);n.work=entries('work').map(x=>x.date<=d&&!x.done?{...x,date:plus(d,1),priority:false,moved:(x.moved||0)+1}:x);if(commit(n))message('Attività spostate al giorno successivo');};
$('shiftForm').onsubmit=e=>{e.preventDefault();const start=$('shiftStart').value,end=$('shiftEnd').value,pauseMinutes=Number($('shiftBreak').value),d=$('date').value,old=shift();$('shiftError').textContent='';if(!validTime(start)||!validTime(end)||min(end)<=min(start)||!Number.isInteger(pauseMinutes)||pauseMinutes<0||pauseMinutes>=min(end)-min(start)){$('shiftError').textContent='Scegli un turno nello stesso giorno e una pausa più breve del turno.';return;}const conflict=data.blocks.find(x=>x.id!==old?.id&&x.date===d&&min(x.start)<min(end)&&min(start)<min(x.end));if(conflict){$('shiftError').textContent=`Si sovrappone a “${conflict.title}”. Modifica il programma in Oggi prima di riservare il turno.`;return;}const n=structuredClone(data);n.blocks=n.blocks.filter(x=>x.id!==old?.id);n.blocks.push({id:old?.id||crypto.randomUUID(),title:'Lavoro',date:d,start,end,pauseMinutes,workShiftDay:d,kind:'fixed',important:old?.important||false,done:old?.done||false});if(commit(n))message('Turno riservato nel programma');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.area||b.dataset.go){switchArea(b.dataset.area||b.dataset.go);return;}const k=b.dataset.check||b.dataset.edit;if(!k)return;const x=entries(k).find(x=>x.id===b.dataset.id);if(!x)return;if(b.dataset.edit){if(k==='shop'){$('shopEditId').value=x.id;$('shopEditName').value=x.title;$('shopEditQty').value=x.qty||'';$('shopEditor').showModal();}else editDaily(k,x);return;}const n=structuredClone(data);n[k]=k==='family'&&!x.done?GiornoDaily.completeFamily(entries(k),x.id,today(),()=>crypto.randomUUID()):entries(k).map(t=>t.id===x.id?{...t,done:!t.done}:t);if(commit(n)&&k==='family'&&x.repeat!=='none'&&!x.done)message('Fatta. La prossima occorrenza è pronta.');});
let notificationRegistration=null,checkingReminder=false;
const reminderSettings=()=>data.reminders||{enabled:false,lead:10};
function reminderStatus(){const r=reminderSettings();$('reminderLead').value=r.lead;$('reminderStatus').textContent=r.enabled?'Avvisi attivi mentre Giorno è aperta e visibile. A telefono bloccato usa il calendario.':'Avvisi disattivati. Puoi sempre usare i promemoria del calendario.';}
$('reminders').onclick=()=>{reminderStatus();if(window.mostraContesti)mostraContesti();$('reminderDialog').showModal();};
$('reminderLead').onchange=()=>{const n=structuredClone(data);n.reminders={...reminderSettings(),lead:Number($('reminderLead').value)};commit(n);};
$('enableReminders').onclick=async()=>{try{if(!('Notification'in window)||!('serviceWorker'in navigator))throw Error('unsupported');const permission=await Notification.requestPermission();if(permission!=='granted'){$('reminderStatus').textContent='Permesso non concesso. Puoi usare gli avvisi del calendario.';return;}notificationRegistration=await navigator.serviceWorker.register('./reminders-sw.js');await navigator.serviceWorker.ready;const n=structuredClone(data);n.reminders={...reminderSettings(),enabled:true};if(commit(n))reminderStatus();}catch{$('reminderStatus').textContent='Questo browser non consente questi avvisi. Usa Calendario per i promemoria sul telefono.';}};
$('disableReminders').onclick=()=>{const n=structuredClone(data);n.reminders={...reminderSettings(),enabled:false};if(commit(n))reminderStatus();};
async function checkReminders(){if(checkingReminder||document.visibilityState!=='visible'||!reminderSettings().enabled||!('Notification'in window)||Notification.permission!=='granted')return;checkingReminder=true;try{let seen=JSON.parse(localStorage.getItem('giorno-reminder-seen')||'[]');if(!Array.isArray(seen))seen=[];const lead=reminderSettings().lead,due=GiornoDaily.due(data.blocks,Date.now(),lead,seen);if(due.length){notificationRegistration=notificationRegistration||await navigator.serviceWorker.register('./reminders-sw.js');await navigator.serviceWorker.ready;for(const b of due){const key=b.id+':'+b.date+':'+b.start+':'+lead;await notificationRegistration.showNotification('Giorno · '+b.start,{body:b.title,tag:key,icon:'icon-192.png'});seen.push(key);message(b.start+' · '+b.title);}localStorage.setItem('giorno-reminder-seen',JSON.stringify(seen.slice(-500)));}}catch{}finally{checkingReminder=false;}}
setInterval(checkReminders,15000);document.addEventListener('visibilitychange',checkReminders);
$('exportReview').onclick=()=>{const time=$('reviewTime').value;if(!validTime(time))return;const d=today().replaceAll('-',''),stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Giorno//Planner//IT','BEGIN:VEVENT','UID:giorno-review@local','DTSTAMP:'+stamp,'DTSTART:'+d+'T'+time.replace(':','')+'00','DURATION:PT5M','RRULE:FREQ=DAILY','SUMMARY:Due minuti per organizzare domani','DESCRIPTION:Apri Giorno e scegli una priorità per domani.','BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:Prepara domani con Giorno','END:VALARM','END:VEVENT','END:VCALENDAR'];download(lines.map(foldLine).join('\r\n')+'\r\n','text/calendar;charset=utf-8','giorno-promemoria-serale.ics');message('Importa il file nel calendario e verifica gli avvisi.');};
renderDaily();

$('dailyName').oninput=()=>{if(editingArea!=='work'){$('workHint').textContent='';return;}
 const s=window.GiornoExtras&&GiornoExtras.durataSuggerita(entries('work'),$('dailyName').value);
 $('workHint').textContent=s?`Le altre volte ci è voluto ${s.minuti} min (misurato ${s.volte===1?'una volta':s.volte+' volte'})`:'';
 if(s&&!$('dailyId').value&&$('workMinutes').value==='30')$('workMinutes').value=s.minuti;};

function riempiLuoghi(sel,valore){if(!sel)return;const l=data.places||[];
 sel.innerHTML='<option value="">Non importa</option>'+l.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');
 sel.value=l.some(p=>p.id===valore)?valore:'';}
$('shopForm').onsubmit=e=>{e.preventDefault();const title=$('shopName').value.trim(),qty=$('shopQty').value.trim();if(!title)return;
 if($('shopShared').checked&&window.GiornoCloud&&window.GiornoCloud.joined()){window.GiornoCloud.add('shop',title,qty);$('shopForm').reset();$('shopShared').checked=true;$('shopName').focus();message('Aggiunto alla lista di tutti.');return;}
 const n=structuredClone(data);n.shop=[...entries('shop'),{id:crypto.randomUUID(),title,qty,done:false}];if(commit(n)){$('shopForm').reset();$('shopName').focus();}};
$('clearShop').onclick=()=>{if(!confirm('Rimuovere dalla lista i prodotti già presi?'))return;const n=structuredClone(data);n.shop=entries('shop').filter(x=>!x.done);commit(n);};
$('shareShop').onclick=async()=>{const left=entries('shop').filter(x=>!x.done);if(!left.length){message('La lista da prendere è vuota.');return;}
 const testo='Lista della spesa\n'+left.map(x=>'☐ '+x.title+(x.qty?' · '+x.qty:'')).join('\n');
 try{if(navigator.share){await navigator.share({title:'Lista della spesa',text:testo});return;}await navigator.clipboard.writeText(testo);message('Lista copiata. Incollala nel messaggio che vuoi inviare.');}
 catch(e){if(e.name!=='AbortError')download(testo,'text/plain;charset=utf-8','lista-spesa.txt','Lista della spesa');}};
$('shopEditForm').onsubmit=e=>{e.preventDefault();const title=$('shopEditName').value.trim();if(!title)return;const n=structuredClone(data);n.shop=entries('shop').map(x=>x.id===$('shopEditId').value?{...x,title,qty:$('shopEditQty').value.trim()}:x);if(commit(n))$('shopEditor').close();};
$('deleteProduct').onclick=()=>{if(!confirm('Eliminare questo prodotto dalla lista?'))return;const n=structuredClone(data);n.shop=entries('shop').filter(x=>x.id!==$('shopEditId').value);if(commit(n))$('shopEditor').close();};
